settings.custom_css:
/* O contêiner principal define o tamanho e o contexto de posicionamento */
selector.botao-play-animado {
    width: 80px;
    height: 80px;
    position: relative;
    overflow: visible;
}

/* Força o LINK CLICÁVEL (o elemento <a>) a ser o círculo e centraliza o ícone */
selector.botao-play-animado .elementor-button {
    width: 100%;
    height: 100%;
    padding: 0;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: all 0.3s ease;
}

/* Garante que o ícone de play tenha o tamanho certo */
selector.botao-play-animado .elementor-button-icon {
    font-size: 28px;
    margin: 0;
}

/* --- EFEITOS (Pulsar e Ripple) --- */

/* EFEITO PULSAR (para fora) */
selector.botao-play-animado::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    animation: pulsar-externo 2s infinite;
    z-index: 0;
    pointer-events: none; /* NOVO: Faz a camada do pulso ser "ignorada" pelo mouse */
}

@keyframes pulsar-externo {
    0% {
        transform: scale(1);
        box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.7);
    }
    100% {
        transform: scale(1.5);
        box-shadow: 0 0 0 25px rgba(255, 255, 255, 0);
    }
}

/* EFEITO RIPPLE (ao clicar) */
selector.botao-play-animado::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 5px;
    height: 5px;
    background: rgba(255, 255, 255, 0.5);
    opacity: 0;
    border-radius: 100%;
    transform: scale(1, 1) translate(-50%);
    transform-origin: 50% 50%;
    z-index: 2;
    pointer-events: none; /* NOVO: Faz a camada do ripple ser "ignorada" pelo mouse */
}

selector.botao-play-animado:active::after {
    transition: 0s;
    transform: scale(30, 30) translate(-50%);
    opacity: 1;
}

/* Garante que o ícone fique na frente */
selector.botao-play-animado .elementor-button-content-wrapper {
    position: relative;
    z-index: 3;
}
